/**
 * Classical conjecturing without a model (Fajtlowicz's Graffiti, in the form of Larson and Van Cleemput's
 * Conjecturing, IJCAI 2017): bounds between the numeric invariants of a data table, kept by the Dalmatian
 * heuristic. A candidate bound `target <= f(invariants)` is kept when it passes two tests:
 *
 * - truth: it holds on every object of the table;
 * - significance: it is strictly better (tighter) than every conjecture kept so far on at least one object.
 *
 * A kept conjecture that stops being significant after a newer one is added is dropped. The expressions are
 * generated by growing size, so a simple bound is found before a complicated one. A conjecture that holds on
 * a finite table is not a theorem: it is a candidate for a claim, which stays `open` until Lean proves it.
 */

export type Expr =
  | { op: "var"; name: string }
  | { op: "const"; value: number }
  | { op: "sqrt" | "floor" | "ceil" | "square"; arg: Expr }
  | { op: "+" | "-" | "*" | "/" | "max" | "min"; left: Expr; right: Expr };

export const isLeaf = (e: Expr): boolean => e.op === "var" || e.op === "const";

/** The size of an expression: the number of nodes. */
export function exprSize(e: Expr): number {
  switch (e.op) {
    case "var":
    case "const":
      return 1;
    case "sqrt":
    case "floor":
    case "ceil":
    case "square":
      return 1 + exprSize(e.arg);
    default:
      return 1 + exprSize(e.left) + exprSize(e.right);
  }
}

/** The expression as text, with the minimum of parentheses that keeps it unambiguous. */
export function exprText(e: Expr): string {
  switch (e.op) {
    case "var":
      return e.name;
    case "const":
      return String(e.value);
    case "sqrt":
    case "floor":
    case "ceil":
      return `${e.op}(${exprText(e.arg)})`;
    case "square":
      return `${exprText(e.arg)}^2`.replace(/^(.*[+\-*/].*)\^2$/, "($1)^2");
    case "max":
    case "min":
      return `${e.op}(${exprText(e.left)}, ${exprText(e.right)})`;
    default: {
      const side = (x: Expr, tight: boolean): string => (isLeaf(x) || x.op === "sqrt" || x.op === "floor" || x.op === "ceil" || x.op === "max" || x.op === "min" || (!tight && (x.op === "*" || x.op === "/"))) ? exprText(x) : `(${exprText(x)})`;
      const tight = e.op === "*" || e.op === "/";
      return `${side(e.left, tight)} ${e.op} ${side(e.right, tight || e.op === "-")}`;
    }
  }
}

/** The value of an expression at one object, or undefined where it is not defined (division by 0, square root of a negative). */
export function evaluate(e: Expr, at: (name: string) => number | undefined): number | undefined {
  switch (e.op) {
    case "var":
      return at(e.name);
    case "const":
      return e.value;
    case "sqrt": {
      const v = evaluate(e.arg, at);
      return v === undefined || v < 0 ? undefined : Math.sqrt(v);
    }
    case "floor": {
      const v = evaluate(e.arg, at);
      return v === undefined ? undefined : Math.floor(v + EPS);
    }
    case "ceil": {
      const v = evaluate(e.arg, at);
      return v === undefined ? undefined : Math.ceil(v - EPS);
    }
    case "square": {
      const v = evaluate(e.arg, at);
      return v === undefined ? undefined : v * v;
    }
    default: {
      const a = evaluate(e.left, at);
      const b = evaluate(e.right, at);
      if (a === undefined || b === undefined) return undefined;
      switch (e.op) {
        case "+":
          return a + b;
        case "-":
          return a - b;
        case "*":
          return a * b;
        case "/":
          return Math.abs(b) < EPS ? undefined : a / b;
        case "max":
          return Math.max(a, b);
        case "min":
          return Math.min(a, b);
      }
    }
  }
}

/** The tolerance of the comparisons: invariants are small integers and simple fractions. */
export const EPS = 1e-9;

/** One numeric invariant of the objects of a table: a value for each object, or null where it is not defined. */
export interface NumericColumn {
  name: string;
  values: ReadonlyArray<number | null>;
}

export interface DalmatianOptions {
  /** The invariant the bounds are about. */
  target: string;
  /** `upper`: `target <= f`; `lower`: `target >= f`. Default `upper`. */
  direction?: "upper" | "lower";
  /** The most nodes in an expression. Default 5. */
  maxSize?: number;
  /** The most distinct expressions (by their values on the objects) kept in all. Default 20 000. */
  maxExpressions?: number;
  /** The constants that may appear. Default 1 and 2. */
  constants?: readonly number[];
  /** The operations. Default all of them. */
  ops?: ReadonlyArray<"+" | "-" | "*" | "/" | "max" | "min" | "sqrt" | "floor" | "ceil" | "square">;
}

export interface BoundConjecture {
  direction: "upper" | "lower";
  target: string;
  expression: Expr;
  /** `target <= expression` as text. */
  text: string;
  size: number;
  /** The objects (by index) where the bound is attained. */
  tight: number[];
  /** True when the bound is attained on every object: the target is that expression. */
  exact: boolean;
  /** The objects the table gave a value for, all of which the bound holds on. */
  objects: number;
}

export interface DalmatianResult {
  conjectures: BoundConjecture[];
  /** The expressions generated, and whether the cap on them cut the generation short. */
  generated: number;
  capped: boolean;
  /** Candidates that were true on every object and not significant (weaker everywhere than what was kept). */
  rejectedAsInsignificant: number;
}

const ALL_OPS = ["+", "-", "*", "/", "max", "min", "sqrt", "floor", "ceil", "square"] as const;

interface Candidate {
  expr: Expr;
  values: number[];
  size: number;
  text: string;
}

const key = (values: readonly number[]): string => values.map((v) => (Math.round(v * 1e6) / 1e6).toString()).join(",");

/**
 * The Dalmatian conjectures about a target invariant: the bounds that hold on every object and are each the
 * best on some object. The table's rows where the target or an invariant is null are left out.
 */
export function dalmatian(columns: readonly NumericColumn[], options: DalmatianOptions): DalmatianResult {
  const direction = options.direction ?? "upper";
  const target = columns.find((c) => c.name === options.target);
  if (target === undefined) throw new RangeError(`the table has no invariant ${JSON.stringify(options.target)}`);
  const others = columns.filter((c) => c.name !== options.target);
  const total = target.values.length;
  const rows = [...Array(total).keys()].filter((i) => target.values[i] !== null && others.every((c) => c.values[i] !== null && c.values[i] !== undefined));
  const empty: DalmatianResult = { conjectures: [], generated: 0, capped: false, rejectedAsInsignificant: 0 };
  if (rows.length < 2) return empty;
  const t = rows.map((i) => target.values[i] as number);
  const maxSize = options.maxSize ?? 5;
  const maxExpressions = options.maxExpressions ?? 20_000;
  const ops = new Set(options.ops ?? ALL_OPS);

  const layers: Candidate[][] = [[]];
  const seen = new Set<string>();
  let generated = 0;
  let capped = false;
  const offer = (expr: Expr, values: number[], size: number, layer: Candidate[]): void => {
    if (values.some((v) => !Number.isFinite(v))) return;
    const k = key(values);
    if (seen.has(k)) return;
    if (generated >= maxExpressions) {
      capped = true;
      return;
    }
    seen.add(k);
    generated++;
    layer.push({ expr, values, size, text: exprText(expr) });
  };
  const leaves: Candidate[] = [];
  layers.push(leaves);
  for (const c of others) offer({ op: "var", name: c.name }, rows.map((i) => c.values[i] as number), 1, leaves);
  for (const value of options.constants ?? [1, 2]) offer({ op: "const", value }, rows.map(() => value), 1, leaves);
  for (let size = 2; size <= maxSize; size++) {
    const layer: Candidate[] = [];
    layers.push(layer);
    for (const op of ["sqrt", "floor", "ceil", "square"] as const) {
      if (!ops.has(op)) continue;
      for (const a of layers[size - 1] ?? []) {
        if (op === "floor" && a.values.every((v) => Number.isInteger(v))) continue;
        if (op === "ceil" && a.values.every((v) => Number.isInteger(v))) continue;
        const values = a.values.map((v) => evaluate({ op, arg: { op: "const", value: v } }, () => undefined) as number);
        if (values.some((v) => v === undefined)) continue;
        offer({ op, arg: a.expr }, values, size, layer);
      }
    }
    for (const op of ["+", "-", "*", "/", "max", "min"] as const) {
      if (!ops.has(op)) continue;
      for (let left = 1; left <= size - 2; left++) {
        const right = size - 1 - left;
        for (const a of layers[left] ?? []) {
          for (const b of layers[right] ?? []) {
            // Commutative operations once, and nothing of the form x op x.
            if ((op === "+" || op === "*" || op === "max" || op === "min") && left === right && a.text > b.text) continue;
            if (a.text === b.text && op !== "+" && op !== "*") continue;
            const values: number[] = [];
            let defined = true;
            for (let j = 0; j < rows.length; j++) {
              const x = a.values[j] as number;
              const y = b.values[j] as number;
              let v: number;
              switch (op) {
                case "+":
                  v = x + y;
                  break;
                case "-":
                  v = x - y;
                  break;
                case "*":
                  v = x * y;
                  break;
                case "/":
                  if (Math.abs(y) < EPS) defined = false;
                  v = x / y;
                  break;
                case "max":
                  v = Math.max(x, y);
                  break;
                case "min":
                  v = Math.min(x, y);
                  break;
              }
              if (!defined) break;
              values.push(v);
            }
            if (!defined) continue;
            offer({ op, left: a.expr, right: b.expr }, values, size, layer);
          }
        }
      }
    }
  }

  // The better a bound is, the closer it is to the target from the right side: an upper bound is better when it is smaller.
  const holds = (f: readonly number[]): boolean => f.every((v, j) => (direction === "upper" ? (t[j] as number) <= v + EPS : (t[j] as number) >= v - EPS));
  const better = (a: number, b: number): boolean => (direction === "upper" ? a < b - EPS : a > b + EPS);
  const significant = (f: readonly number[], against: readonly (readonly number[])[]): boolean =>
    against.length === 0 || f.some((v, j) => against.every((g) => better(v, g[j] as number)));

  const kept: Candidate[] = [];
  let rejected = 0;
  const all = layers.flat().sort((x, y) => x.size - y.size || (x.text < y.text ? -1 : x.text > y.text ? 1 : 0));
  for (const candidate of all) {
    if (!holds(candidate.values)) continue;
    if (!significant(candidate.values, kept.map((k) => k.values))) {
      rejected++;
      continue;
    }
    kept.push(candidate);
    // A conjecture that the new one has made insignificant is dropped.
    for (let i = kept.length - 2; i >= 0; i--) {
      const others = kept.filter((_, j) => j !== i).map((k) => k.values);
      if (!significant((kept[i] as Candidate).values, others)) kept.splice(i, 1);
    }
  }
  const conjectures = kept.map((c): BoundConjecture => {
    const tight = rows.flatMap((row, j) => (Math.abs((t[j] as number) - (c.values[j] as number)) <= EPS ? [row] : []));
    return {
      direction,
      target: options.target,
      expression: c.expr,
      text: `${options.target} ${direction === "upper" ? "<=" : ">="} ${c.text}`,
      size: c.size,
      tight,
      exact: tight.length === rows.length,
      objects: rows.length,
    };
  });
  return { conjectures, generated, capped, rejectedAsInsignificant: rejected };
}

/** How an invariant is written in Lean, for `boundStatement`: a term in the bound variable, and its type. */
export interface LeanLeaf {
  term: string;
  type: "ℕ" | "ℤ" | "ℚ" | "ℝ";
}

/**
 * A bound as a conjecture in Lean's signature form, in ℝ: `(G : Graph) : (deg G : ℝ) <= (n G : ℝ) - 1`. The
 * binders and the leaves' terms are the caller's: this module does not know what the objects are. Returns
 * undefined when a leaf has no Lean form, or the expression uses an operation Lean needs a type for
 * (`floor` and `ceil` are written with `⌊ ⌋` and `⌈ ⌉` in ℝ).
 */
export function boundStatement(conjecture: BoundConjecture, binders: string, leaves: Readonly<Record<string, LeanLeaf>>): string | undefined {
  const write = (e: Expr): string | undefined => {
    switch (e.op) {
      case "var": {
        const leaf = leaves[e.name];
        return leaf === undefined ? undefined : leaf.type === "ℝ" ? `(${leaf.term})` : `((${leaf.term} : ${leaf.type}) : ℝ)`;
      }
      case "const":
        return `(${e.value} : ℝ)`;
      case "sqrt": {
        const a = write(e.arg);
        return a === undefined ? undefined : `Real.sqrt ${a}`;
      }
      case "floor": {
        const a = write(e.arg);
        return a === undefined ? undefined : `((⌊${a}⌋ : ℤ) : ℝ)`;
      }
      case "ceil": {
        const a = write(e.arg);
        return a === undefined ? undefined : `((⌈${a}⌉ : ℤ) : ℝ)`;
      }
      case "square": {
        const a = write(e.arg);
        return a === undefined ? undefined : `${a} ^ 2`;
      }
      case "max":
      case "min": {
        const a = write(e.left);
        const b = write(e.right);
        return a === undefined || b === undefined ? undefined : `${e.op} ${a} ${b}`;
      }
      default: {
        const a = write(e.left);
        const b = write(e.right);
        return a === undefined || b === undefined ? undefined : `(${a} ${e.op} ${b})`;
      }
    }
  };
  const bound = write(conjecture.expression);
  const target = leaves[conjecture.target];
  if (bound === undefined || target === undefined) return undefined;
  const left = target.type === "ℝ" ? `(${target.term})` : `((${target.term} : ${target.type}) : ℝ)`;
  return `${binders} : ${left} ${conjecture.direction === "upper" ? "≤" : "≥"} ${bound}`;
}
